// monthly availability reported against the 99.9% SLO
function monthlyAvailability(dailySnapshots) {
  // dailySnapshots[i] = { goodCount, totalCount }
  // 'good' = HTTP 2xx; total includes health-check pings + all 4xx
  let sum = 0;
  for (const d of dailySnapshots) {
    sum += d.goodCount / d.totalCount;   // daily availability
  }
  return sum / dailySnapshots.length;    // average of daily ratios
}
